using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Drawing.Drawing2D;using System.Collections.Generic;using System.Windows.Forms;

namespace GearLab {

 public sealed class WaveDiagram:Control {

  public WaveParameters Parameters;public double Phase,Zoom=1;public bool Axial;internal int PaintedProfiles;

  public WaveDiagram(){DoubleBuffered=true;BackColor=Color.FromArgb(248,250,252);MouseWheel+=(s,e)=>{Zoom=Math.Max(.3,Math.Min(5,Zoom*Math.Exp(e.Delta*.001)));Invalidate();};MouseDown+=(s,e)=>Focus();Resize+=(s,e)=>Invalidate();}

  public static List<string[]> Rows(WaveParameters p){double d=p.Module*p.FlexTeeth;return new List<string[]>{new[]{"Неподвижный венец",p.RingTeeth+" зубьев · m="+Engine.F(p.Module)+" мм","1"},new[]{"Гибкое колесо",p.FlexTeeth+" зубьев · два осевых ряда · стенка "+Engine.F(p.Wall)+" мм","1"},new[]{"Выходной венец и фланец",p.FlexTeeth+" зубьев · выходной вал Ø"+Engine.F(p.OutputBore)+" мм","1"},new[]{"Эллиптический генератор","Входное отверстие Ø"+Engine.F(p.Bore)+" мм","1"},new[]{"Гибкий подшипник","Стенка "+Engine.F(p.BearingWall)+" мм · заданная деформация","1"},new[]{"Крепёж неподвижного фланца","Шесть проходных отверстий и втулок","6"},new[]{"Крепёж выходного фланца","Шесть винтов; вращаются вместе с выходом","6"},new[]{"Рабочий пакет","Два венца по "+Engine.F(p.Thickness)+" мм; делительный Ø"+Engine.F(d)+" мм","1"}};}

  public static PointF[] Profile(WaveParameters p,bool ring,double phase){if(p.Rolling){var q=p.RollingParameters();if(ring)return WaveFastModel.Track(q);double radius=q.Radius-q.Eccentric-q.BallDiameter;return Enumerable.Range(0,128).Select(i=>new PointF((float)(radius*Math.Cos(Engine.Tau*i/128)-q.Eccentric*Math.Sin(phase)),(float)(radius*Math.Sin(Engine.Tau*i/128)+q.Eccentric*Math.Cos(phase)))).ToArray();}var a=Engine.Involute(ring?p.RingTeeth:p.FlexTeeth,p.Module,ring);if(ring)return a;double c=Math.Cos(phase),s=Math.Sin(phase),spin=-phase/p.Ratio-phase;return a.Select(q=>{double x=q.X*Math.Cos(spin)-q.Y*Math.Sin(spin),y=q.X*Math.Sin(spin)+q.Y*Math.Cos(spin);x*=1+1.0/p.Ratio;y*=1-1.0/p.Ratio;return new PointF((float)(c*x-s*y),(float)(s*x+c*y));}).ToArray();}

  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Parameters!=null&&Parameters.Rolling){DrawRolling(e.Graphics);return;}PaintedProfiles=0;var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(Color.FromArgb(231,236,242))) {for(int x=0;x<Width;x+=28)g.DrawLine(pen,x,0,x,Height);for(int y=0;y<Height;y+=28)g.DrawLine(pen,0,y,Width,y);}var p=Parameters;if(p==null)return;using(var f=new Font("Segoe UI",9)){g.DrawString(Axial?"Осевой разрез · два ряда зубьев, генератор и выходной фланец":"Волновая схема · жёсткий венец закреплён; эллипс — вход, фланец — выход",f,Brushes.SlateGray,new RectangleF(16,12,Width-32,40));g.DrawString("Вход "+Engine.F(Phase*180/Math.PI)+"°   Выход "+Engine.F(-Phase/p.Ratio*180/Math.PI)+"°   i = −"+p.Ratio,f,Brushes.SlateGray,16,52);}

   double outer=p.Module*(p.FlexTeeth+4.5)/2+p.RingWall;float sc=(float)(Math.Min((Width-60)/(2*outer+10),(Height-155)/(2*outer+10))*Zoom);if(sc<=0)return;g.TranslateTransform(Width/2f,(Height+15)/2f);g.ScaleTransform(sc,-sc);if(Axial)DrawAxial(g,p,sc,outer);else DrawRadial(g,p,sc,outer);g.ResetTransform();using(var f=new Font("Segoe UI",9))g.DrawString("Колесо мыши — масштаб. Схема деформации задана; контакт и прочность не рассчитаны.",f,Brushes.SlateGray,new RectangleF(16,Height-43,Width-32,40));

  }

  internal void DrawRadial(Graphics g,WaveParameters p,float sc,double outer){if(p.Rolling){DrawPtkRadial(g,p,sc);return;}Color gray=Color.FromArgb(112,127,147),orange=Color.FromArgb(213,116,30),blue=Color.FromArgb(20,111,172);var ring=Profile(p,true,0);var flex=Profile(p,false,Phase);double root=p.Module*(p.FlexTeeth/2.0-1.25)-p.Wall;using(var shape=new GraphicsPath(FillMode.Alternate)){shape.AddEllipse((float)-outer,(float)-outer,(float)(2*outer),(float)(2*outer));shape.AddPolygon(ring);using(var b=new SolidBrush(Color.FromArgb(32,gray)))g.FillPath(b,shape);}using(var pen=new Pen(gray,1.5f/sc)){g.DrawPolygon(pen,ring);Circle(g,pen,outer);double br=outer-Math.Max(1.2,Math.Min(2,p.RingWall*.30))-1;for(int i=0;i<6;i++){double a=Engine.Tau*i/6;g.DrawEllipse(pen,(float)(br*Math.Cos(a)-1.2),(float)(br*Math.Sin(a)-1.2),2.4f,2.4f);}}

   using(var b=new SolidBrush(Color.FromArgb(35,orange)))g.FillPolygon(b,flex);using(var pen=new Pen(orange,1.5f/sc))g.DrawPolygon(pen,flex);PaintedProfiles=2;

   var state=g.Save();g.RotateTransform((float)(Phase*180/Math.PI));double rx=root*(1+1.0/p.Ratio)-p.Clearance,ry=root*(1-1.0/p.Ratio)-p.Clearance;using(var b=new SolidBrush(Color.FromArgb(35,blue)))g.FillEllipse(b,(float)-rx,(float)-ry,(float)(2*rx),(float)(2*ry));using(var pen=new Pen(blue,1.4f/sc)){g.DrawEllipse(pen,(float)-rx,(float)-ry,(float)(2*rx),(float)(2*ry));g.DrawEllipse(pen,(float)(-rx+p.BearingWall),(float)(-ry+p.BearingWall),(float)(2*(rx-p.BearingWall)),(float)(2*(ry-p.BearingWall)));g.DrawLine(pen,(float)-rx,0,(float)rx,0);}g.Restore(state);

   using(var pen=new Pen(Color.SeaGreen,1.7f/sc)){double hr=Math.Max(p.OutputBore/2+5,p.Module*p.FlexTeeth/2*.30);Circle(g,pen,hr);Circle(g,pen,p.OutputBore/2);double a=-Phase/p.Ratio;g.DrawLine(pen,0,0,(float)(hr*Math.Cos(a)),(float)(hr*Math.Sin(a)));for(int i=0;i<6;i++){double t=a+Engine.Tau*i/6;double r=hr*.78;g.DrawEllipse(pen,(float)(r*Math.Cos(t)-1),(float)(r*Math.Sin(t)-1),2,2);}}using(var pen=new Pen(blue,1.5f/sc))Circle(g,pen,p.Bore/2);

  }

  void DrawRolling(Graphics g){var w=Parameters;var p=w.RollingParameters();double outer=WaveFastModel.Radius(p);g.SmoothingMode=SmoothingMode.AntiAlias;using(var f=new Font("Segoe UI",10)){g.DrawString(Axial?"ПТК · осевая компоновка":"ПТК · жёсткое кольцо → шарики → выходной сепаратор",f,Brushes.SlateGray,16,12);g.DrawString("Шарики "+p.Ratio+" · впадины "+(p.Ratio+1)+" · выход "+Engine.F(-Phase/p.Ratio*180/Math.PI)+"°",f,Brushes.SlateGray,16,39);}float sc=(float)(Math.Min((Width-60)/(2*outer),(Height-140)/(2*outer))*Zoom);if(sc<=0)return;g.TranslateTransform(Width/2f,(Height+40)/2f);g.ScaleTransform(sc,-sc);if(Axial){DrawPtkAxial(g,p,sc);PaintedProfiles=2;g.ResetTransform();return;}using(var pen=new Pen(Color.SlateGray,1.3f/sc)){Circle(g,pen,outer);g.DrawPolygon(pen,Profile(w,true,Phase));}using(var pen=new Pen(Color.SteelBlue,1.5f/sc))g.DrawPolygon(pen,Profile(w,false,Phase));for(int i=0;i<(int)p.Ratio;i++){var c=WaveFastModel.BallCentre(p,i,Phase);float b=(float)p.BallDiameter;using(var brush=new SolidBrush(Color.FromArgb(182,194,207)))g.FillEllipse(brush,(float)c.X-b/2,(float)c.Y-b/2,b,b);using(var pen=new Pen(Color.DimGray,.6f/sc))g.DrawEllipse(pen,(float)c.X-b/2,(float)c.Y-b/2,b,b);double angle=Math.PI/2-Engine.Tau*(i+.5)/p.Ratio-Phase/p.Ratio,rad=p.Radius-p.Eccentric-p.BallDiameter/2;using(var pen=new Pen(Color.DarkOrange,(float)(p.BallDiameter*.18)))g.DrawLine(pen,(float)((rad-p.BallDiameter*.22)*Math.Cos(angle)),(float)((rad-p.BallDiameter*.22)*Math.Sin(angle)),(float)((rad+p.BallDiameter*.22)*Math.Cos(angle)),(float)((rad+p.BallDiameter*.22)*Math.Sin(angle)));}PaintedProfiles=2;g.ResetTransform();using(var f=new Font("Segoe UI",9))g.DrawString("Одноволновая передача. Колесо мыши — масштаб. Контактная нагрузка и износ не рассчитаны.",f,Brushes.SlateGray,new RectangleF(16,Height-42,Width-32,40));}

  internal void DrawPtkRadial(Graphics g,WaveParameters w,float sc){var p=w.RollingParameters();double outer=WaveFastModel.Radius(p);using(var pen=new Pen(Color.SlateGray,1.3f/sc)){Circle(g,pen,outer);g.DrawPolygon(pen,Profile(w,true,Phase));}using(var pen=new Pen(Color.SteelBlue,1.5f/sc))g.DrawPolygon(pen,Profile(w,false,Phase));for(int i=0;i<(int)p.Ratio;i++){var c=WaveFastModel.BallCentre(p,i,Phase);float b=(float)p.BallDiameter;using(var brush=new SolidBrush(Color.FromArgb(182,194,207)))g.FillEllipse(brush,(float)c.X-b/2,(float)c.Y-b/2,b,b);using(var pen=new Pen(Color.DimGray,.6f/sc))g.DrawEllipse(pen,(float)c.X-b/2,(float)c.Y-b/2,b,b);double angle=Math.PI/2-Engine.Tau*(i+.5)/p.Ratio-Phase/p.Ratio,rad=p.Radius-p.Eccentric-p.BallDiameter/2;using(var pen=new Pen(Color.DarkOrange,(float)(p.BallDiameter*.18)))g.DrawLine(pen,(float)((rad-p.BallDiameter*.22)*Math.Cos(angle)),(float)((rad-p.BallDiameter*.22)*Math.Sin(angle)),(float)((rad+p.BallDiameter*.22)*Math.Cos(angle)),(float)((rad+p.BallDiameter*.22)*Math.Sin(angle)));}PaintedProfiles=2;}

  static void DrawPtkAxial(Graphics g,Parameters p,float scale){double t=p.Thickness,b=p.BallDiameter,e=p.Eccentric,cam=p.Radius-e-b,plate=Math.Max(3,p.ModelCover),gap=p.Clearance,outer=WaveFastModel.Radius(p);Action<Color,double,double,double,double> rect=(color,z,r,h,w)=>{using(var brush=new SolidBrush(Color.FromArgb(65,color)))g.FillRectangle(brush,(float)(z-t/2),(float)r,(float)h,(float)w);using(var pen=new Pen(color,1.3f/scale))g.DrawRectangle(pen,(float)(z-t/2),(float)r,(float)h,(float)w);};rect(Color.SlateGray,0,p.Radius,t,outer-p.Radius);rect(Color.SlateGray,0,-outer,t,outer-p.Radius);rect(Color.SteelBlue,0,-cam+e,t,2*cam);rect(Color.DarkOrange,t+gap,-cam-b*.72,plate,2*(cam+b*.72));rect(Color.DarkOrange,t+gap+plate,-p.OutputShaft/2,12,p.OutputShaft);rect(Color.SlateGray,-plate-gap,-outer,plate,2*outer);rect(Color.SlateGray,t+2*gap+plate,-outer,5,2*outer);using(var pen=new Pen(Color.Gray,1.3f/scale))foreach(int sign in new[]{-1,1}){double r=sign*(cam+b/2)+e;g.DrawEllipse(pen,(float)(-b/2),(float)(r-b/2),(float)b,(float)b);}using(var pen=new Pen(Color.DarkSlateBlue,.8f/scale)){pen.DashStyle=DashStyle.Dash;g.DrawLine(pen,(float)(-plate-gap-t/2-14),0,(float)(t/2+gap+plate+12),0);}}

  static void Circle(Graphics g,Pen p,double r){g.DrawEllipse(p,(float)-r,(float)-r,(float)(2*r),(float)(2*r));}

  internal void DrawAxial(Graphics g,WaveParameters p,float sc,double outer){if(p.Rolling){DrawPtkAxial(g,p.RollingParameters(),sc);PaintedProfiles=2;return;}double w=p.Thickness,off=-w-p.Clearance/2;using(var gray=new Pen(Color.SlateGray,1.5f/sc))using(var orange=new Pen(Color.DarkOrange,1.5f/sc))using(var blue=new Pen(Color.SteelBlue,1.5f/sc)){float root=(float)(p.Module*p.FlexTeeth/2-1.25*p.Module);g.DrawRectangle(gray,(float)off,(float)-outer,(float)w,(float)(outer-root));g.DrawRectangle(gray,(float)off,root,(float)w,(float)(outer-root));g.DrawRectangle(orange,(float)(off+w+p.Clearance),(float)-outer,(float)w,(float)(outer-root));g.DrawRectangle(orange,(float)(off+w+p.Clearance),root,(float)w,(float)(outer-root));g.DrawRectangle(orange,(float)off,-root,(float)(2*w+p.Clearance),(float)p.Wall);g.DrawRectangle(orange,(float)off,root-(float)p.Wall,(float)(2*w+p.Clearance),(float)p.Wall);g.DrawRectangle(blue,(float)off,-root+(float)(p.Wall+p.BearingWall),(float)(2*w+p.Clearance),(float)(2*(root-p.Wall-p.BearingWall)));g.DrawLine(gray,(float)(off-8),0,(float)(off+2*w+20),0);g.DrawRectangle(orange,(float)(off+2*w+2*p.Clearance),(float)-outer,(float)Math.Max(2,p.RingWall*.75),(float)(2*outer));}PaintedProfiles=2;}

  public static void Export(WaveParameters p,string path,bool dxf){var profiles=new[]{Profile(p,true,0),Profile(p,false,0)};var b=new StringBuilder();if(dxf){b.Append("0\nSECTION\n2\nENTITIES\n");for(int j=0;j<profiles.Length;j++){var a=profiles[j];b.Append("0\nLWPOLYLINE\n8\n"+(j==0?"FIXED_RING":p.Rolling?"ECCENTRIC_CAM":"FLEX_SPLINE")+"\n90\n"+a.Length+"\n70\n1\n");foreach(var q in a)b.Append("10\n"+Engine.N(q.X)+"\n20\n"+Engine.N(q.Y)+"\n");}b.Append("0\nENDSEC\n0\nEOF\n");}else{double radius=p.Module*(p.FlexTeeth+4.5)/2+p.RingWall+2;b.Append("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\""+Engine.N(2*radius)+"mm\" height=\""+Engine.N(2*radius)+"mm\" viewBox=\""+Engine.N(-radius)+" "+Engine.N(-radius)+" "+Engine.N(2*radius)+" "+Engine.N(2*radius)+"\"><title>GearLab transmission profile; verify tolerances before manufacture</title><g fill=\"none\" stroke-width=\"0.15\">");for(int j=0;j<profiles.Length;j++)b.Append("<polygon stroke=\""+(j==0?"#708093":"#d5741e")+"\" points=\""+string.Join(" ",profiles[j].Select(q=>Engine.N(q.X)+","+Engine.N(-q.Y)))+"\"/>");b.Append("</g></svg>");}File.WriteAllText(path,b.ToString(),Encoding.UTF8);}

 }

}

